const sourceLink = key => `<a href="${SOURCES[key][1]}" target="_blank" rel="noopener">${SOURCES[key][0]}</a>`
export const DEMAND_CATALOG = SERIES.map(item => ({
  id: item.id, theme: item.theme,
  ...Object.fromEntries(['pt', 'en', 'es'].map(lang => [lang, { live: true, slug: item[lang].slug, title: item[lang].title, teaser: item[lang].description }])),
}))

export function getDemandArticle(id, lang) {
  const item = SERIES.find(a => a.id === id)
  if (!item || !COPY[lang]) throw new Error(`Unknown demand article: ${id}/${lang}`)
  const a = item[lang], c = COPY[lang]
  // Highlight one phrase; never put punctuation immediately after it.
  const words = a.title.split(' ')
  const h1 = words.length > 3 ? `${words.slice(0, -2).join(' ')} <span class="word-highlight">${words.slice(-2).join(' ')}</span>` : a.title
  return {
    id, slug: a.slug, short: a.title, date: '2026-11-09', titleTag: a.meta,
    description: a.description, keywords: a.keywords, h1, lead: a.lead,
    blocks: [
      { summary: [a.yes, a.no, c.summary] },
      { h2: c.science, id: 'base', toc: c.science },
      ...a.science.map(p => ({ p })),
      { p: `${c.source} ${item.sources.map(sourceLink).join(' · ')}.` },
      { h2: c.practice, id: 'atividades', toc: c.practice },
      { p: c.examples }, { cards: a.cards },
      { h2: c.adapt, id: 'adaptar', toc: c.adapt },
      { p: a.adapt }, { p: c.routine },
      { h2: c.help, id: 'apoio', toc: c.help }, { p: a.help },
      { h2: c.limits, id: 'limites', toc: c.limits },
      { evidence: { yes: [a.yes], no: [a.no] } },
      { bridge: { title: c.bridgeTitle, intro: c.bridgeIntro, items: BRIDGES[item.bridge][lang], outro: c.bridgeLimit } },
      { note: c.note },
    ],
    faqTitle: c.faq, faq: a.faq, sources: item.sources.map(sourceLink), related: item.related,
  }
}
